position. These conditions stay out of the beginner palette.</p><div id="spatial-condition-list"></div></section><div class="form-grid"><label>Then<select id="route-destination"></select></label><label>Terminal outcome<select id="route-outcome"><option value="">Continue</option><option value="complete">Complete</option><option value="fail">Fail</option></select></label></div><div class="section-title actions-title"><div><span class="eyebrow">Effects</span><h3>Actions</h3></div><div class="inline"><select id="new-action-type"></select><button id="add-action" class="quiet">Add</button></div></div><div id="action-list"></div></div></div></aside>
      </section>
