function attemptHtml(t,index){let state=attemptState(t);return`<div class="trace-row attempt ${state}"><span class="trace-mark" aria-hidden="true">${state==='done'?'✓':'○'}</span><span class="trace-name">Try ${index+1}. ${esc(eventLabel(t.event_name,t.target))}</span><span class="trace-detail">${esc((t.effects||[]).join(' · ')||t.deadline||'The quest is waiting for this beat.')}</span><span class="trace-ok ${state}">${esc(attemptNote(t))}</span></div>`}
function beatHtml(beat,index){let rows=beat.rows,last=rows[rows.length-1],state=beat.done?'done':rows.some(t=>attemptState(t)==='partial')?'partial':'idle',label=rows[0].beat||eventLabel(last.event_name,last.target),detail=beat.done?(last.effects||[]).join(' · ')||last.next_instruction||'':last.deadline||last.next_instruction||'The quest is waiting for this beat.';return`<div class="trace-beat ${state}"><div class="trace-row beat ${state}"><span class="trace-mark" aria-hidden="true">${beat.done?'✓':'○'}</span><span class="trace-name">${index+1}. ${esc(label)}</span><span class="trace-detail">${esc(detail)}</span><span class="trace-ok ${state}">${esc(attemptNote(last))}</span></div>${rows.length>1?`<div class="trace-attempts">${rows.map(attemptHtml).join('')}</div>`:''}</div>`}
function renderRehearsal(){let card=$('#rehearsal-result'),badge=$('#rehearsal-badge');if(!project){badge.className='readiness neutral';badge.textContent='No quest';card.className='result-card empty';card.textContent='Choose a quest before rehearsing it.';return}if(!rehearsalResult){badge.className='readiness neutral';badge.textContent='Not run';card.className='result-card empty';card.textContent=rehearsalSteps.length?`${rehearsalSteps.length} player action(s) queued.`:'Run the guided rehearsal to check the selected path before anything publishes.';renderJourney();return}let d=rehearsalResult,finished=!!d.outcome,failed=d.outcome==='fail',limits=d.limitations||[],paths=d.available_paths||[],trace=d.trace||[];badge.className=`readiness ${failed?'bad':finished?'good':'warn'}`;badge.textContent=failed?'Fail path':finished?'Complete':'In progress';card.className='result-card';card.innerHTML=`<div class="result-head"><span class="${failed?'bad-ink':'good-ink'}">${failed?'Selected path reached a fail outcome':finished?'Selected path checked':'Selected path in progress'}</span><span class="result-meta">${trace.length} step${trace.length===1?'':'s'} · current beat: ${esc(stageName(d.current_node_id))}</span></div>${traceBeats(trace).map((beat,index)=>beatHtml(beat,index)).join('')||'<div class="empty">No player actions have been tried yet.</div>'}${limits.length?`<div class="path-note"><strong>Coverage limits · ${limits.length}</strong>${limits.map(x=>`<div class="limit-row"><span>▸</span><span>${esc(x)}</span></div>`).join('')}${paths.length?`<small>Available paths: ${esc(paths.join(', '))}</small>`:''}</div>`:''}<p class="disclaimer">${esc(d.disclaimer||'Browser rehearsal does not prove a live Valheim adapter.')}</p>`;renderJourney()}
async function runRehearsal(scenarioId,mode='manual'){if(!project){status('Choose a quest first','Rehearsal needs a saved draft.',true);return}if(!(await saveNow()))return;let sequence=beginOperation('rehearsal'),context=requestContext(),steps=mode==='guided'?[]:clone(rehearsalSteps);if(scenarioId){let s=catalog.scenarios.find(x=>x.id===scenarioId);steps=clone(s?.steps||[])}rehearsalSteps=steps;try{let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/rehearse`,{method:'POST',body:JSON.stringify({mode,path_id:null,scenario_id:scenarioId||null,steps})});if(!isLatestOperation('rehearsal',sequence)||!isCurrentContext(context))return;rehearsalResult=d;liveNodeId=d.current_node_id;if(mode==='guided')rehearsalSteps=clone(d.generated_steps||[]);renderCanvas();renderRehearsal();status('Rehearsal complete',d.outcome?`Preview reached ${d.outcome}.`:`Current beat: ${stageName(d.current_node_id)}.`)}catch(e){if(!isLatestOperation('rehearsal',sequence)||!isCurrentContext(context))return;rehearsalResult=null;$('#rehearsal-badge').className='readiness bad';$('#rehearsal-badge').textContent='Needs attention';$('#rehearsal-result').className='result-card';$('#rehearsal-result').textContent=JSON.stringify(e.diagnostics||e,null,2);renderJourney();status('Rehearsal rejected',e.error||'The quest graph is invalid.',true)}}
