async function playRevision(){if(!project||publishPending){if(!project)status('Choose a quest first','There is no draft to play.',true);return}showStage('publish');$('#publish-diagnostic').hidden=true;setPublishLock(true);try{let checked=await certify(false);if(!(await saveNow()))throw{error:'save_failed'};let context=requestContext();if(!isCurrentContext(context)||context.revision!==checked.request_context.revision)throw{error:'stale_request'};let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/play`,{method:'POST',body:JSON.stringify({expected_revision:context.revision})});if(!isCurrentContext(context))return;status(`Playing ${project.title}`,`Revision r${context.revision} transferred. The armed game owns activation.`);await refreshRuntime()}catch(e){if(e.status===409&&e.conflict&&e.project){project=e.project;dirty=false;selectedNodeId=project.entry_node_id;selectedRouteId=node()?.routes?.[0]?.id||null;rehearsalResult=null;runtimeState=null;renderAll();status('Newer draft loaded','Play stopped because this project changed. Review the current draft and try again.',true)}else if(e.error==='stale_request')status('Play paused','The draft changed after validation. Check the current revision again.',true);else if(e.error){showDiagnostic(e);status('Revision rejected',e.error,true)}}finally{setPublishLock(false)}}
async function publish(){if(!project||publishPending){if(!project)status('Choose a quest first','There is no draft to publish.',true);return}showStage('publish');$('#publish-diagnostic').hidden=true;setPublishLock(true);try{let certified=await certify(true);if(!(await saveNow()))throw{error:'save_failed'};let context=requestContext();if(!isCurrentContext(context)||context.revision!==certified.request_context.revision)throw{error:'stale_request'};let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/publish`,{method:'POST',body:JSON.stringify({expected_revision:context.revision})});if(!isCurrentContext(context))return;status('Published to Runtime inbox',`${d.receipt.pack_id} ${d.receipt.version} - ${d.receipt.content_hash}`);await refreshRuntime()}catch(e){if(e.status===409&&e.conflict&&e.project){project=e.project;let migrated=normalizeProjectRoutes(project);dirty=migrated;selectedNodeId=project.entry_node_id;selectedRouteId=node()?.routes?.[0]?.id||null;rehearsalResult=null;runtimeState=null;saveState(migrated?'Saving migration...':'Reloaded newer draft',migrated?'dirty':'bad');renderAll();status('Newer draft loaded','Publish stopped because this project changed after certification. Review the newer draft and publish again.',true);if(migrated){editGeneration++;clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,0)}}else if(e.error==='same_version_hash_collision')status('Version already published','Start a new iteration from the project actions menu.',true);else if(e.error==='stale_request')status('Publish paused','The draft changed after certification. Check it again before publishing.',true);else if(e.error){showDiagnostic(e);status('Publish rejected',e.error,true)}}finally{setPublishLock(false)}}
